import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"橫渠易說 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"橫渠易說 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"classics/hengqu/054.md","filePath":"classics/hengqu/054.md"}'),l={name:"classics/hengqu/054.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>雖處喧閧，亦無害於為學。有人於此，或日月而至焉，亦有終日而不至者，及其久也，去者常少。若居於家，聞嬰孩之啼則有不忍之心，聞奴婢喧戾則猶有不容之意，至於市井紛囂一不與我事，何傷於存誠養志!易曰：“艮其背，不獲其身，行其庭，不見其人，無咎。”夫入他人之庭，不見其人可止也，艮其背至近於人也，然且不見，以其上下無應也。“時止則止，時行則行，動靜不失其時，其道光明”，學者必時其動靜，則其道乃不蔽昧而明白。今人從學之久，不見進長，正以莫識動靜，見他人擾擾，非關己事而所修亦廢。由聖學觀之，冥冥悠悠，以是終身，謂之光明可乎？</p><h3 id="彖曰-艮-止也-時止則止-時行則行-動靜不失其時-其道光明。艮其止-止其所也-上下敵應-不相與也-是以不獲其身-行其庭-不見其人-無咎也。" tabindex="-1">彖曰：艮，止也，時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也，上下敵應，不相與也，是以不獲其身，行其庭，不見其人，無咎也。 <a class="header-anchor" href="#彖曰-艮-止也-時止則止-時行則行-動靜不失其時-其道光明。艮其止-止其所也-上下敵應-不相與也-是以不獲其身-行其庭-不見其人-無咎也。" aria-label="Permalink to “彖曰：艮，止也，時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也，上下敵應，不相與也，是以不獲其身，行其庭，不見其人，無咎也。”">​</a></h3><p>［動靜不失其時，是時措之宜也，集義也，集義久則自有光明。靜則無見，必動乃見。其道光明，以其本之光明，故其發也光明。］ 易言“光明”者，多艮之象，著則明之義也。</p><h3 id="象曰-兼山艮-君子以思不出其位。" tabindex="-1">象曰：兼山艮，君子以思不出其位。 <a class="header-anchor" href="#象曰-兼山艮-君子以思不出其位。" aria-label="Permalink to “象曰：兼山艮，君子以思不出其位。”">​</a></h3><p>位，所安之分也。如“素夷狄行乎夷狄，素患難行乎患難”。</p><h3 id="初六-艮其趾-無咎-利永貞。-象曰-艮其趾-未失正也。" tabindex="-1">初六，艮其趾，無咎，利永貞。 象曰：“艮其趾”，未失正也。 <a class="header-anchor" href="#初六-艮其趾-無咎-利永貞。-象曰-艮其趾-未失正也。" aria-label="Permalink to “初六，艮其趾，無咎，利永貞。 象曰：“艮其趾”，未失正也。”">​</a></h3><h3 id="六二-艮其腓-不拯其隨-其心不快。-象曰-不拯其隨-未退聽也。" tabindex="-1">六二，艮其腓，不拯其隨，其心不快。 象曰：“不拯其隨”，未退聽也。 <a class="header-anchor" href="#六二-艮其腓-不拯其隨-其心不快。-象曰-不拯其隨-未退聽也。" aria-label="Permalink to “六二，艮其腓，不拯其隨，其心不快。 象曰：“不拯其隨”，未退聽也。”">​</a></h3><p>腓，體之隨也，不能禁其趾而徒止其腓，腓所未聽，故心不能快。</p><h3 id="九三-艮其限-列其夤-厲薰心。-象曰-艮其限-危薰心也。" tabindex="-1">九三，艮其限，列其夤，厲薰心。 象曰：“艮其限”，危薰心也。 <a class="header-anchor" href="#九三-艮其限-列其夤-厲薰心。-象曰-艮其限-危薰心也。" aria-label="Permalink to “九三，艮其限，列其夤，厲薰心。 象曰：“艮其限”，危薰心也。”">​</a></h3><p>一身而動止中列，危至薰心。</p><h3 id="六四-艮其身-無咎。-象曰-艮其身-止諸躬也。" tabindex="-1">六四，艮其身，無咎。 象曰：“艮其身”，止諸躬也。 <a class="header-anchor" href="#六四-艮其身-無咎。-象曰-艮其身-止諸躬也。" aria-label="Permalink to “六四，艮其身，無咎。 象曰：“艮其身”，止諸躬也。”">​</a></h3><p>止於心，故能艮其身，鹹之九四“朋從爾思”義近之。</p><h3 id="六五-艮其輔-言有序-悔亡。-象曰-艮其輔-以中正也。" tabindex="-1">六五，艮其輔，言有序，悔亡。 象曰：“艮其輔”，以中正也。 <a class="header-anchor" href="#六五-艮其輔-言有序-悔亡。-象曰-艮其輔-以中正也。" aria-label="Permalink to “六五，艮其輔，言有序，悔亡。 象曰：“艮其輔”，以中正也。”">​</a></h3><p>不能施止於心而能止其言，故悔可亡也。</p><h3 id="上九-敦-艮吉。-象曰-敦艮之吉-以厚終也。" tabindex="-1">上九，敦，艮吉。 象曰：敦艮之吉，以厚終也。 <a class="header-anchor" href="#上九-敦-艮吉。-象曰-敦艮之吉-以厚終也。" aria-label="Permalink to “上九，敦，艮吉。 象曰：敦艮之吉，以厚終也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
